using System.Collections.Concurrent;
using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var notebook = new ResearchNotebook();

AITool[] tools =
[
    AIFunctionFactory.Create(WebSearchTool.SearchAsync,
        name: "web_search",
        description: "Search the web for information on a query. Returns relevant snippets."),

    AIFunctionFactory.Create(notebook.SaveNote,
        name: "save_note",
        description: "Save a research note with a title and content for later reference."),

    AIFunctionFactory.Create(notebook.GetAllNotes,
        name: "get_notes",
        description: "Retrieve all saved research notes to review findings so far."),
];

var agent = new ChatClientAgent(chatClient, tools)
{
    Name = "ResearchAgent",
    Instructions = """
        You are a research assistant. When given a topic:
        1. Search the web multiple times with different queries to gather broad information.
        2. Save key findings as notes using the save_note tool.
        3. Review your notes with get_notes.
        4. Provide a comprehensive summary with key facts and source attributions.
        Be thorough — perform at least 2-3 searches before summarizing.
        """,
};

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (MAF)        ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine("Enter a topic to research, or 'quit' to exit.\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(topic) ||
        topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    List<ChatMessage> history =
    [
        new(ChatRole.User,
            $"Research the following topic and provide a detailed summary: {topic}"),
    ];

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
    };

    Console.WriteLine("\nResearching…\n");

    await foreach (var update in agent.InvokeStreamingAsync(history, options))
    {
        if (!string.IsNullOrEmpty(update.Text))
            Console.Write(update.Text);
    }

    Console.WriteLine("\n");
}

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------

internal static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(
        [Description("The search query to look up on the web")] string query)
    {
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}" +
                  "&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await Http.GetStringAsync(url);
            // Extract the useful portions of the DuckDuckGo instant-answer response
            using var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var sb = new StringBuilder();
            AppendIfPresent(sb, "Abstract", root);
            AppendIfPresent(sb, "AbstractSource", root);
            AppendIfPresent(sb, "AbstractURL", root);

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var t in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    if (t.TryGetProperty("Text", out var text))
                    {
                        sb.AppendLine($"- {text.GetString()}");
                        count++;
                    }
                }
            }

            var result = sb.ToString();
            return string.IsNullOrWhiteSpace(result)
                ? $"No instant-answer results for '{query}'. Try a more specific query."
                : result;
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static void AppendIfPresent(StringBuilder sb, string property,
        System.Text.Json.JsonElement root)
    {
        if (root.TryGetProperty(property, out var el))
        {
            var value = el.GetString();
            if (!string.IsNullOrWhiteSpace(value))
                sb.AppendLine($"{property}: {value}");
        }
    }
}

internal sealed class ResearchNotebook
{
    private readonly ConcurrentDictionary<string, string> _notes = new();

    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Content of the research note")] string content)
    {
        _notes[title] = content;
        return $"✓ Note saved: \"{title}\"";
    }

    public string GetAllNotes()
    {
        if (_notes.IsEmpty)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        foreach (var (title, content) in _notes)
            sb.AppendLine($"## {title}\n{content}\n");
        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

